                if i + 1 < len(line) and line[i + 1] == '\n':
                    i += 2
                    break
                else:
                    i += 1
                    break
            elif c == '\n':
                i += 1
                break
            elif c == delimiter:
                break
            else:
                content += c
                i += 1

        return (content, i)
